tests.body:
const { performance } = await import("perf_hooks");
const httpStub = await import("node:http");

// Start a slow local HTTP server that responds after 8 seconds
const delayMs = 8000;
const port = await httpStub.startSlowServer(delayMs);

// Patch workspace webhookUrl to point to local slow server
await prisma.workspace.update({ where: { id: workspace.id }, data: { webhookUrl: `http://localhost:${port}/webhook` } });

const start = performance.now();
let result = null;
let error = null;
try {
  result = await createFeedbackAction(workspaceSlug, {}, validFormData);
} catch (e) {
  error = e;
}
const end = performance.now();
const elapsedMs = end - start;

record("result", result);
record("error", error ? String(error) : null);
record("elapsedMs", elapsedMs);

await httpStub.stopServer();

// The claim is that the function blocks and takes a long time due to awaiting webhook
harm_observed(elapsedMs >= 4000, "createFeedbackAction took at least 4 seconds due to awaiting slow webhook")

// Remove webhookUrl from workspace to disable webhook
await prisma.workspace.update({ where: { id: workspace.id }, data: { webhookUrl: null } });

const result = await createFeedbackAction(workspaceSlug, {}, validFormData);
record("result", result);

check(result.success === true, "createFeedbackAction returns success when no webhook configured")

const invalidFormData = new FormData();
invalidFormData.set("title", "x"); // too short
invalidFormData.set("body", "Valid body");

const result = await createFeedbackAction(workspaceSlug, {}, invalidFormData);
record("result", result);

check(result.error === "Give it a short title", "createFeedbackAction returns validation error for short title")
